mapper.insert:
insert into city_fairness_event (
    source_ref, event_id, outing_id, kind, actor_id, occurred_at, known_at,
    subject_source, subject_event_id, join_time, team_size, action_cost, newcomer,
    gain_amount, verification_millis, board_id, region_id, season_id, rules_version
) values (
    #{source}, #{eventId}, #{outingId}, #{kind}, #{actorId}, #{occurredAt}, #{knownAt},
    #{subjectSource}, #{subjectEventId}, #{joinTime}, #{teamSize}, #{actionCost}, #{newcomer},
    #{gainAmount}, #{verificationMillis},
    #{boardId}, #{regionId}, #{seasonId}, #{rulesVersion}
)

insert into city_fairness_read (
    account_id, query_id, as_of, board_id, region_id, season_id, rules_version, payload
) values (
    #{accountId}, #{queryId}, #{asOf}, #{boardId}, #{regionId}, #{seasonId}, #{rulesVersion}, #{payload}
)

mapper.select:
select account_id as accountId,
       query_id as queryId,
       as_of as asOf,
       board_id as boardId,
       region_id as regionId,
       season_id as seasonId,
       rules_version as rulesVersion,
       payload
from city_fairness_read
where account_id = #{accountId}
  and query_id = #{queryId}
  and board_id = #{boardId}
  and region_id = #{regionId}
  and season_id = #{seasonId}
  and rules_version = #{rulesVersion}
